<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/functions.php';
require_admin(); $pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $sessionId=filter_input(INPUT_POST,'session_id',FILTER_VALIDATE_INT); if(!$sessionId){flash('error','Invalid session.');redirect('admin/sessions.php');} $delete=$pdo->prepare('DELETE FROM sessions WHERE id=?');$delete->execute([$sessionId]);flash('success','Session deleted. Its statistics no longer affect rankings.');redirect('admin/sessions.php'); }
$sessions=$pdo->query("SELECT s.*,COUNT(sp.id) participant_count,COUNT(CASE WHEN sp.excluded=0 THEN 1 END) eligible_count,p.name pod_name FROM sessions s LEFT JOIN session_players sp ON sp.session_id=s.id LEFT JOIN players p ON p.id=s.player_of_day_id GROUP BY s.id,p.name ORDER BY s.session_date DESC,s.id DESC")->fetchAll();
$pageTitle='Sessions';$adminPage='sessions';require dirname(__DIR__).'/includes/admin-header.php';
?>
<div class="admin-titlebar"><div><p class="eyebrow">Cricket days</p><h1>Sessions</h1><p>Create, edit, or carefully remove complete scorecards.</p></div><div class="admin-actions"><a class="btn btn-primary" href="<?= e(url('admin/session-form.php')) ?>">+ Add session</a></div></div>
<?php if($sessions):?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Date</th><th>Session</th><th>Players</th><th>Eligible</th><th>Player of the Day</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($sessions as $session):?><tr><td><strong><?= e(format_date($session['session_date'])) ?></strong></td><td><?= e($session['title']?:$session['location']) ?><small class="muted"><?= e($session['location']) ?></small></td><td><?= (int)$session['participant_count']?></td><td><?= (int)$session['eligible_count']?></td><td><?= e($session['pod_name']?:'—')?></td><td><span class="pill <?= $session['status']==='cancelled'?'inactive':''?>"><?= e($session['status'])?></span></td><td><div class="row-actions"><a class="small-button" href="<?= e(url('admin/session-form.php?id='.(int)$session['id']))?>">Edit</a><?php if($session['status']==='completed'):?><a class="small-button" href="<?= e(url('session.php?id='.(int)$session['id']))?>">View</a><?php endif;?><form method="post" data-confirm="Delete this entire session? Its statistics will be removed from every ranking."><?= csrf_field()?><input type="hidden" name="session_id" value="<?= (int)$session['id']?>"><button class="small-button danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="surface admin-empty"><h2>No sessions yet</h2><p>Add players first, then record your first cricket day.</p><a class="btn btn-primary" href="<?= e(url('admin/session-form.php'))?>">Add first session</a></div><?php endif;?>
<?php require dirname(__DIR__).'/includes/admin-footer.php';?>
